LL solve(LL n, int x, LL m) { int k = x + 1; vector<LL> y(k + 1, 0); vector<int> pr; vector<bool> ip(k + 1, true); y[0] = 0; if (k >= 1) y[1] = 1; for (int i = 2; i <= k; i++) { if (ip[i]) { pr.push_back(i); y[i] = bigmod(i, x, m); } for (int p : pr) { if (i * p > k) break; ip[i * p] = false; y[i * p] = (y[i] * y[p]) % m; if (i % p == 0) break; } } for (int i = 1; i <= k; i++) { y[i] = (y[i - 1] + y[i]) % m; } if (n <= k) return y[n]; vector<LL> f(k + 1, 1), iF(k + 1, 1); for (int i = 1; i <= k; i++) { f[i] = (f[i - 1] * i) % m; } iF[k] = bigmod(f[k], m - 2, m); for (int i = k - 1; i >= 0; i--) { iF[i] = (iF[i + 1] * (i + 1)) % m; } vector<LL> L(k + 1), R(k + 1); LL nm = n % m; L[0] = nm; for (int i = 1; i <= k; i++) { L[i] = (L[i - 1] * (nm - i + m) % m) % m; } R[k] = (nm - k + m) % m; for (int i = k - 1; i >= 0; i--) { R[i] = (R[i + 1] * (nm - i + m) % m) % m; } LL res = 0; for (int i = 0; i <= k; i++) { LL nu = 1; if (i > 0) nu = (nu * L[i - 1]) % m; if (i < k) nu = (nu * R[i + 1]) % m; LL de = (iF[i] * iF[k - i]) % m; if ((k - i) % 2 == 1) { de = (m - de) % m; } LL t = (y[i] * nu) % m; t = (t * de) % m; res = (res + t) % m; } return res; }
